BEGIN TRANSACTION;
CREATE TABLE activities (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        vtuber_id INTEGER,
        title TEXT NOT NULL,
        description TEXT,
        event_date DATE NOT NULL,
        link_url TEXT,
        activity_type TEXT CHECK(activity_type IN ('milestone', 'announcement', 'x_post', 'other')),
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (vtuber_id) REFERENCES vtubers(id) ON DELETE CASCADE
    );
INSERT INTO "activities" VALUES(5,1,'滔滔饕餮初配信!',NULL,'2026-01-11',NULL,'milestone','2026-07-14 08:51:32');
