INSERT INTO "activities" VALUES(7,1,'YT突破1.7萬訂閱',NULL,'2026-07-11',NULL,'milestone','2026-07-16 07:01:12');
INSERT INTO "activities" VALUES(8,7,'星璃 畢業','星璃 正式畢業','2026-09-30',NULL,'milestone','2026-11-04 08:02:44');
CREATE TABLE artists (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name_main TEXT NOT NULL,
        name_ja TEXT,
        name_zh TEXT,
        name_romaji TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    , name_en TEXT, wikidata_id TEXT);
