	video_id VARCHAR NOT NULL, 
	title VARCHAR NOT NULL, 
	published_at DATE, 
	video_type VARCHAR NOT NULL, 
	thumbnail_url VARCHAR, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
